import java.sql.*;

public class UserAuth {
    public boolean authenticate(String username, String password) {
        // Secure: Using prepared statement to prevent SQL injection
        String query = "SELECT * FROM users WHERE username = ? AND password = ?";

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "pass");
             PreparedStatement pstmt = conn.prepareStatement(query)) {

            pstmt.setString(1, username); // Safely sets the username parameter
            pstmt.setString(2, password); // Safely sets the password parameter

            try (ResultSet rs = pstmt.executeQuery()) {
                return rs.next(); // Returns true if user exists
            }
        } catch (SQLException e) {
            e.printStackTrace();
            return false;
        }
    }
}
